BODY.direct_parameters:
    int valid;

    if (ListIndexR >= 500)
        return;
    if (row < 0)
        goto invalid;
    if (row > 63)
        goto invalid;
    if (column < 1)
        goto invalid;
    if (column > 63)
        goto invalid;
    valid = 1;
    goto checked;
invalid:
    valid = 0;
checked:
    if (valid) {
        DigTileR(row, column);
        AddAntToRList(row, column, life, 8, 0);
        LifeR[(row << 6) + column] = (unsigned char)life;
    }

BODY.register_local_copies:
    register int rowCopy = row;
    register int columnCopy = column;
    int valid;

    if (ListIndexR >= 500)
        return;
    if (rowCopy < 0)
        goto invalid;
    if (rowCopy > 63)
        goto invalid;
    if (columnCopy < 1)
        goto invalid;
    if (columnCopy > 63)
        goto invalid;
    valid = 1;
    goto checked;
invalid:
    valid = 0;
checked:
    if (valid) {
        DigTileR(rowCopy, columnCopy);
        AddAntToRList(rowCopy, columnCopy, life, 8, 0);
        LifeR[(rowCopy << 6) + columnCopy] = (unsigned char)life;
    }
